  private hazardZone(
    id: string,
    type: 'water' | 'kill',
    options: HazardVolumeOptions,
    penaltyStrokes: number,
  ): ZoneDescriptor {
    const zone: ZoneDescriptor = { id, type, bounds: aabb(options.position, options.size), penaltyStrokes };
