    const surface: SurfaceDescriptor = {
      id: this.useId(prefix, options.id),
      transform: { position: clone(options.position) },
      shape,
      size: clone(options.size),
      material: options.material ?? 'green',
    };
    if (rotation) surface.transform.rotation = rotation;
    if (options.friction !== undefined) surface.friction = options.friction;
    if (options.restitution !== undefined) surface.restitution = options.restitution;
    this.surfaces.push(surface);
    return this;
  }

  private pushObstacle(prefix: string, input: ObstacleInput): this {
    const id = this.useId(prefix, input.id);
    this.obstacles.push({ ...input, id } as unknown as ObstacleDescriptor);
    return this;
  }

  private nextId(prefix: string): string {
    this.counter += 1;
    return `${prefix}-${this.counter}`;
  }

  private useId(prefix: string, id?: string): string {
    const value = id ?? this.nextId(prefix);
    if (this.usedIds.has(value)) throw new Error(this.message(`duplicate element id "${value}"`));
    this.usedIds.add(value);
    return value;
  }

  private message(text: string): string {
    return `Hole ${this.options.id}: ${text}`;
  }
